void *mutt_hash_find(const struct Hash *table, const char *strkey) /* <=== mutt_hash_find */ 
{
  union HashKey key;
  key.strkey = strkey;
  return union_hash_find(table, key);
}

void *mutt_mem_calloc(size_t nmemb, size_t size) /* <=== mutt_mem_calloc */ 
{
  void *p = NULL;

  if (!nmemb || !size)
    return NULL;

  if (nmemb > (SIZE_MAX / size))
  {
    mutt_error(_("Integer overflow -- can't allocate memory!"));
    mutt_exit(1);
  }

  p = calloc(nmemb, size);
  if (!p)
  {
    mutt_error(_("Out of memory!"));
    mutt_exit(1);
  }
  return p;
}

size_t mutt_str_strfcpy(char *dest, const char *src, size_t dsize) /* <=== mutt_str_strfcpy */ 
{
  if (!dest || (dsize == 0))
    return 0;
  if (!src)
  {
    dest[0] = '\0';
    return 0;
  }

  char *dest0 = dest;
  while ((--dsize > 0) && (*src != '\0'))
    *dest++ = *src++;

  *dest = '\0';
  return (dest - dest0);
}

static void *union_hash_find(const struct Hash *table, union HashKey key) /* <=== union_hash_find */ 
{
  struct HashElem *ptr = union_hash_find_elem(table, key);
  if (ptr)
    return ptr->data;
  else
    return NULL;
}

void nntp_group_unread_stat(struct NntpData *nntp_data) /* <=== nntp_group_unread_stat */ 
{
  nntp_data->unread = 0;
  if (nntp_data->last_message == 0 || nntp_data->first_message > nntp_data->last_message)
    return;

  nntp_data->unread = nntp_data->last_message - nntp_data->first_message + 1;
  for (unsigned int i = 0; i < nntp_data->newsrc_len; i++)
  {
    anum_t first = nntp_data->newsrc_ent[i].first;
    if (first < nntp_data->first_message)
      first = nntp_data->first_message;
    anum_t last = nntp_data->newsrc_ent[i].last;
    if (last > nntp_data->last_message)
      last = nntp_data->last_message;
    if (first <= last)
      nntp_data->unread -= last - first + 1;
  }
}

struct HashElem *mutt_hash_typed_insert(struct Hash *table, const char *strkey, /* <=== mutt_hash_typed_insert */ 
                                        int type, void *data)
{
  union HashKey key;
  key.strkey = table->strdup_keys ? mutt_str_strdup(strkey) : strkey;
  return union_hash_insert(table, key, type, data);
}

void *mutt_mem_malloc(size_t size) /* <=== mutt_mem_malloc */ 
{
  void *p = NULL;

  if (size == 0)
    return NULL;
  p = malloc(size);
  if (!p)
  {
    mutt_error(_("Out of memory!"));
    mutt_exit(1);
  }
  return p;
}

struct HashElem *mutt_hash_insert(struct Hash *table, const char *strkey, void *data) /* <=== mutt_hash_insert */ 
{
  return mutt_hash_typed_insert(table, strkey, -1, data);
}

static struct NntpData *nntp_data_find(struct NntpServer *nserv, const char *group) /* <=== nntp_data_find */ 
{
  struct NntpData *nntp_data = mutt_hash_find(nserv->groups_hash, group);
  if (nntp_data)
    return nntp_data;

  size_t len = strlen(group) + 1;
  /* create NntpData structure and add it to hash */
  nntp_data = mutt_mem_calloc(1, sizeof(struct NntpData) + len);
  nntp_data->group = (char *) nntp_data + sizeof(struct NntpData);
  mutt_str_strfcpy(nntp_data->group, group, len);
  nntp_data->nserv = nserv;
  nntp_data->deleted = true;
  mutt_hash_insert(nserv->groups_hash, nntp_data->group, nntp_data);

  /* add NntpData to list */
  if (nserv->groups_num >= nserv->groups_max)
  {
    nserv->groups_max *= 2;
    mutt_mem_realloc(&nserv->groups_list, nserv->groups_max * sizeof(nntp_data));
  }
  nserv->groups_list[nserv->groups_num++] = nntp_data;

  return nntp_data;
}

void mutt_mem_free(void *ptr) /* <=== mutt_mem_free */ 
{
  if (!ptr)
    return;
  void **p = (void **) ptr;
  if (*p)
  {
    free(*p);
    *p = 0;
  }
}

void mutt_str_replace(char **p, const char *s) /* <=== mutt_str_replace */ 
{
  FREE(p);
  *p = mutt_str_strdup(s);
}

void mutt_mem_realloc(void *ptr, size_t size) /* <=== mutt_mem_realloc */ 
{
  void *r = NULL;
  void **p = (void **) ptr;

  if (size == 0)
  {
    if (*p)
    {
      free(*p);
      *p = NULL;
    }
    return;
  }

  r = realloc(*p, size);
  if (!r)
  {
    mutt_error(_("Out of memory!"));
    mutt_exit(1);
  }

  *p = r;
}

char *mutt_str_strdup(const char *str) /* <=== mutt_str_strdup */ 
{
  if (!str || !*str)
    return NULL;

  const size_t len = strlen(str) + 1;
  char *copy = mutt_mem_malloc(len);
  memcpy(copy, str, len);
  return copy;
}

